/* Human rooms are separate from the existing browser-local solo save. */
(()=>{'use strict';
const KEY='spark-online-room-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),sym={O:'✦',B:'◆',P:'⬡',X:'⇆'};
let lang='he',room=null,latest=null,invite='',error='',busy=false,animating=false,seen=0,timer=null,kind='hand',index=0,color=null,slot=null,swap=null,frame=null,awards=null,narration='',animationActor=0,epoch=0;
const t=(he,en)=>lang==='he'?he:en,root=()=>document.getElementById('online-root'),name=c=>({O:t('כתום','Orange'),B:t('כחול','Blue'),P:t('סגול','Purple'),X:'SHIFT'})[c],uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16));
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const params=new URLSearchParams(location.hash.slice(1));let roomId=params.get('room')||saved.id||'',joinToken=params.get('invite')||'';
function persist(){localStorage.setItem(KEY,JSON.stringify({id:roomId,invite:invite||'',name:saved.name||''}))}
async function api(path,body){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const res=await fetch('/api/rooms'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller.signal,cache:'no-store'});const data=await res.json();if(!res.ok)throw Object.assign(Error(data.error||'server_error'),{code:data.error,status:res.status});return data}finally{clearTimeout(timeout)}}
const errors={sign_in_required:['צריך להתחבר ל־ChatGPT.','Sign in with ChatGPT.'],not_member:['כדי להצטרף צריך לפתוח את קישור ההזמנה המלא.','Open the full invite link to join.'],invalid_invite:['קישור ההזמנה אינו תקין.','This invitation is invalid.'],room_full:['החדר מלא או שהמשחק כבר התחיל.','The room is full or has already started.'],room_expired:['תוקף החדר הסתיים אחרי 24 שעות. אפשר ליצור חדר חדש.','The room expired after 24 hours. Create a new room.'],room_not_found:['החדר לא נמצא.','Room not found.'],stale_revision:['הלוח עודכן. רעננו את המהלך לפני ניסיון נוסף.','The board changed. Review your move and try again.'],not_your_turn:['כרגע תורו של שחקן אחר.','It is another player’s turn.'],waiting_for_players:['ממתינים לכל השחקנים.','Waiting for all players.'],room_limit:['כבר יצרת עשרה חדרים פעילים. נסה שוב אחרי שתוקפם יסתיים.','You already created ten active rooms. Try after they expire.'],rooms_unavailable:['המשחק המשותף אינו זמין כרגע.','Online rooms are unavailable.']};
function message(e){return errors[e.code]?t(...errors[e.code]):t('החיבור לא הושלם. המהלך לא נשלח שוב אוטומטית; בדוק את הלוח אחרי חיבור מחדש.','Connection interrupted. The move is not automatically retried; check the board after reconnecting.')}
function reset(){kind='hand';index=0;color=null;slot=null;swap=null}
function card(c,hand=null,hit=false){return `<${hand===null?'div':'button'} class="card c${c} ${hit?'hit':''} ${hand===index&&kind==='hand'?'chosen':''}" ${hand===null?'':`data-online-hand="${hand}" aria-pressed="${index===hand&&kind==='hand'}"`} aria-label="${name(c)}"><span class="corner">${sym[c]}</span><strong>${sym[c]}</strong><small>${name(c)}</small></${hand===null?'div':'button'}>`}
function form(){return `<section class="sheet"><span class="eyebrow">${t('חברים אמיתיים · חדר פרטי','REAL FRIENDS · PRIVATE ROOM')}</span><h1>${joinToken?t('הוזמנת לשולחן','You are invited'):t('משחקים יחד','Play together')}</h1><p>${t('כל אחד רואה רק את היד שלו. הלוח והתורות מסונכרנים, ואפשר לחזור אחרי רענון.','Each player sees only their own hand. The row and turns sync, and you can return after a refresh.')}</p><label for="online-name">${t('השם שלך בשולחן','Your table name')}</label><input id="online-name" maxlength="28" value="${esc(saved.name)}" autocomplete="nickname">${joinToken?`<button id="online-join" class="primary full" ${busy?'disabled':''}>${t('הצטרף למשחק','Join game')}</button>`:`<label for="online-mode">${t('מצב משחק','Game mode')}</label><select id="online-mode"><option value="A">A · Classic+ · 8</option><option value="B" selected>B · Extended · 9</option><option value="C">C · SHIFT · 9</option></select><label for="online-capacity">${t('מספר שחקנים כולל אותך','Players including you')}</label><select id="online-capacity"><option value="2">2</option><option value="3">3</option></select><button id="online-create" class="primary full" ${busy?'disabled':''}>${t('צור חדר וקישור הזמנה','Create room and invite link')}</button>`}<p class="small">${t('האתר נשאר פרטי. החבר צריך חשבון ChatGPT והרשאת צפייה באתר; הקישור לבדו לא מעניק הרשאה. פנה לבעל האתר להוספת כתובת החשבון של החבר.','The site stays private. Friends need a ChatGPT account and site access; the link alone does not grant access. Ask the site owner to add the friend’s account email.')}</p>${roomId?`<button id="online-reconnect">${t('נסה להתחבר מחדש','Reconnect')}</button><button id="online-forget">${t('למסך חדר חדש','New-room screen')}</button>`:''}</section>`}
function inviteBlock(){const link=invite?location.origin+'/#'+new URLSearchParams({room:room.id,invite}):'';return `<div class="online-invite"><h2>${t('הזמנת חבר','Invite a friend')}</h2>${link?`<input id="online-link" readonly dir="ltr" aria-label="${t('קישור הזמנה','Invite link')}" value="${esc(link)}"><button id="online-copy">${t('העתק קישור','Copy link')}</button>`:`<p class="small">${t('חזור לדפדפן שבו יצרת את החדר כדי להעתיק את ההזמנה.','Use the browser where you created this room to copy its invitation.')}</p>`}<p class="small">${t('שתף בפרטי בלבד. דרושה גם הרשאת כניסה לאתר. החדר תקף ל־24 שעות.','Share privately. Site access is also required. The room expires in 24 hours.')}</p></div>`}
function table(){const displayedTurn=animating?animationActor:room.turn;const own=room.members[room.me],can=room.status==='playing'&&room.turn===room.me&&!busy&&!animating,board=frame?.board||((swap!==null&&!animating)?SparkEngine.swapped(room.board,swap):room.board),points=awards||room.members.map(m=>m.points),scoring=frame?.kind==='match'?frame.removed:[];const selected=kind==='wild'?color:own.hand?.[index];
return `<section class="table physical-table online-table"><div class="round-line"><span class="eyebrow">${room.mode} · ${t('סיבוב','ROUND')} ${room.round} / 8</span><button id="online-refresh" class="text-button">${t('סנכרן','Sync')}</button></div><div class="opponents">${room.members.map((m,i)=>i===room.me?'':`<div class="seat ${displayedTurn===i?'active-seat':''}"><div class="seat-person"><b>${esc(m.name)}</b><span class="turn-tag">${displayedTurn===i?t('משחק','PLAYING'):t('ממתין','WAITING')}</span></div><div class="backs" aria-label="${t('שלושה קלפים מוסתרים','Three hidden cards')}"><i>⚡</i><i>⚡</i><i>⚡</i></div><div class="collector"><b>${points[i]}</b></div><small>🌈 ${m.wild} · ⇄ ${m.swap}</small></div>`).join('')}</div><div class="table-piles"><div class="stock"><span>⚡</span></div><small>${t('שולחן משותף · ידיים פרטיות','SHARED TABLE · PRIVATE HANDS')}</small><div class="discard"><span>↗</span></div></div><div class="row-zone"><div class="row-label">${board.length} ${t('קלפים בשורה','cards in row')}</div><div class="online-track"><div class="online-board" style="--count:${Math.max(board.length,room.rowSize)}">${board.map((c,i)=>`<div data-online-card="${i}">${card(c,null,scoring.includes(i))}</div>`).join('')}</div>${can?`<div class="online-gaps" style="--count:${kind==='swap'?room.rowSize-1:room.rowSize+1}">${Array.from({length:kind==='swap'?room.rowSize-1:room.rowSize+1},(_,i)=>`<button data-online-slot="${i}" aria-label="${kind==='swap'?t('זוג','Pair'):t('רווח','Gap')} ${i+1}" aria-pressed="${slot===i}" class="${slot===i?'selected':''}">${kind==='swap'?'⇄':'+'}<small>${i+1}</small></button>`).join('')}</div>`:''}</div><p class="small centered">${t('החלק את השורה כדי להגיע לכל הרווחים.','Swipe the row to reach every gap.')}</p></div><div class="narration" role="status"><h2>${animating?esc(room.members[animationActor].name)+' · '+esc(narration):room.status==='finished'?t('המשחק הסתיים','Game finished'):room.turn===room.me?t('התור שלך','Your turn'):t('התור של ','Waiting for ')+esc(room.members[room.turn].name)}</h2><p>${animating?'':swap!==null?t('ההחלפה מוכנה. כעת הנח קלף רגיל; שתי הפעולות ייפתרו יחד.','Swap is prepared. Place a normal card; both actions resolve together.'):kind==='wild'?t('בחר צבע ורווח. הג׳וקר מחליף את ההנחה הרגילה.','Choose a color and gap. Wild replaces your regular placement.'):can?t('בחר קלף ורווח ואז אשר הנחה.','Choose a card and gap, then confirm.'):t('הלוח מתעדכן אוטומטית. אפשר לרענן ולחזור לאותו מושב.','The board updates automatically. Refresh to return to your seat.')}</p></div>${room.status==='finished'?`<div class="game-finished sheet"><h2>${t('תוצאות','Results')}</h2>${room.members.map((m,i)=>`<div class="summary-line"><span>${esc(m.name)}</span><b>${m.points}</b></div>`).join('')}<p>${t('מנצחים: ','Winners: ')+room.members.filter(m=>m.points===Math.max(...room.members.map(p=>p.points))).map(m=>esc(m.name)).join(', ')}</p><button id="online-new" class="primary full">${t('צור משחק נוסף','Create another game')}</button></div>`:''}<div class="your-hand"><div class="hand-label"><span>${esc(own.name)} · ${t('היד שלך בלבד','YOUR PRIVATE HAND')}</span><strong>${points[room.me]}</strong></div><div class="hand ${can?'':'online-locked'}">${(own.hand||[]).map((c,i)=>card(c,can?i:null)).join('')}</div>${can?`<div class="specials"><button id="online-wild" ${!own.wild||swap!==null?'disabled':''}>🌈 WILD ×${own.wild}</button><button id="online-swap" ${!own.swap||swap!==null?'disabled':''}>⇄ SWAP ×${own.swap}</button></div>${kind==='wild'?`<div class="colors">${['O','B','P'].map(c=>`<button data-online-color="${c}" aria-pressed="${color===c}" class="${color===c?'selected':''}">${sym[c]} ${name(c)}</button>`).join('')}</div>`:''}${swap!==null?`<button id="online-cancel">${t('בטל החלפה מתוכננת','Cancel prepared Swap')}</button>`:''}<button id="online-commit" class="primary full" ${slot===null||kind==='swap'||!selected?'disabled':''}>${t('הנח ואשר','Place and confirm')}</button>`:''}</div><details><summary>${t('חוקי החדר','Room rules')}</summary><p>${t('8 תורות לכל שחקן. רצף של 3 ומעלה נאסף בנקודה לקלף, ואז בודקים שרשראות. SWAP פעם במשחק ואחריו קלף רגיל; WILD פעם במשחק במקום קלף רגיל.','Eight turns each. Runs of 3+ score one per card, then check chains. Swap once plus a normal placement; Wild once instead of a normal card.')}</p>${room.mode==='C'?`<p>SHIFT: ${t('קומבו צמוד מוציא אותו ללא נקודות. הקלף השמאלי עובר לימין, ובודקים שוב.','An adjacent combo removes it for zero points. Move the leftmost card right and check again.')}</p>`:''}</details><button id="online-leave">${t('חזור למסך חדרים','Back to rooms')}</button></section>`}
function render(){const el=root();if(!el)return;el.innerHTML=`${error?`<p class="notice" role="alert">${esc(error)}</p>`:''}${!room?form():room.status==='closed'?`<section class="sheet"><h1>${t('החדר נסגר','Room closed')}</h1><button id="online-forget">${t('חדר חדש','New room')}</button></section>`:room.status==='lobby'?`<section class="sheet"><h1>${t('ממתינים לחברים','Waiting for friends')}</h1><p>${room.members.length} / ${room.capacity} · ${room.mode}</p>${room.members.map((m,i)=>`<div class="summary-line">${esc(m.name)} ${i===room.me?'· '+t('אתה','you'):''}</div>`).join('')}${room.host?inviteBlock():''}<button id="online-start" class="primary full" ${!room.host||room.members.length!==room.capacity||busy?'disabled':''}>${t('כולם כאן · התחל משחק','Everyone is here · Start')}</button>${room.host?`<button id="online-close">${t('סגור חדר','Close room')}</button>`:''}<button id="online-leave">${t('למסך חדרים','Back to rooms')}</button></section>`:table()}`;bind()}
async function action(fn){if(busy||animating)return;busy=true;error='';render();try{await fn()}catch(e){error=message(e);if(e.status===409&&roomId)try{accept(await api('/'+roomId))}catch{}}finally{busy=false;render()}}
async function command(action,extra={}){const data=await api('/'+roomId+'/'+action,{revision:room.revision,requestId:uid(),...extra});await accept(data)}
function showNew(){epoch++;animating=false;room=null;roomId='';joinToken='';invite='';saved={name:saved.name};localStorage.removeItem(KEY);history.replaceState(null,'',location.pathname);render()}
function bind(){const on=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn};on('online-create',()=>{const nameValue=document.getElementById('online-name').value.trim(),mode=document.getElementById('online-mode').value,capacity=+document.getElementById('online-capacity').value;if(!nameValue){error=t('כתוב שם כדי להצטרף לשולחן.','Enter a table name.');return render()}saved.name=nameValue;action(async()=>{room=await api('',{name:nameValue,mode,capacity});roomId=room.id;history.replaceState(null,'',location.pathname+'#room='+roomId);invite=room.inviteToken;delete room.inviteToken;seen=0;persist()})});on('online-join',()=>{const nameValue=document.getElementById('online-name').value.trim();if(!nameValue){error=t('כתוב שם.','Enter your name.');return render()}saved.name=nameValue;action(async()=>{room=await api('/'+roomId+'/join',{token:joinToken,name:nameValue});joinToken='';invite='';seen=room.events.at(-1)?.id||0;history.replaceState(null,'',location.pathname+'#room='+roomId);persist()})});on('online-start',()=>action(()=>command('start')));on('online-close',()=>action(()=>command('close')));on('online-reconnect',refresh);on('online-refresh',refresh);on('online-forget',showNew);on('online-new',showNew);on('online-leave',()=>{epoch++;animating=false;room=null;roomId='';error='';render()});on('online-copy',async()=>{const el=document.getElementById('online-link');try{await navigator.clipboard.writeText(el.value);document.getElementById('online-copy').textContent=t('הועתק','Copied')}catch{el.focus();el.select()}});for(const el of document.querySelectorAll('[data-online-hand]'))el.onclick=()=>{kind='hand';index=+el.dataset.onlineHand;color=null;slot=null;render()};for(const el of document.querySelectorAll('[data-online-slot]'))el.onclick=()=>{if(kind==='swap'){swap=+el.dataset.onlineSlot;kind='hand';slot=null}else slot=+el.dataset.onlineSlot;render()};for(const el of document.querySelectorAll('[data-online-color]'))el.onclick=()=>{color=el.dataset.onlineColor;render()};on('online-wild',()=>{kind='wild';color=null;slot=null;render()});on('online-swap',()=>{kind='swap';slot=null;render()});on('online-cancel',()=>{reset();render()});on('online-commit',()=>{const move={kind,index,color:kind==='wild'?color:room.members[room.me].hand[index],pos:slot,...(swap!==null?{swapPos:swap}:{})};action(()=>command('move',{move}))})}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
function positions(){return [...document.querySelectorAll('[data-online-card]')].map(el=>({rect:el.getBoundingClientRect(),html:el.innerHTML}))}
async function visualStep(step,previous,event,serial){if(epoch!==serial)return;const before=positions();frame=step;narration=step.kind==='swap'?t('⇄ החלפה · ההנחה עדיין באותו תור','⇄ Swap · placement follows in the same turn'):step.kind==='placed'?(event.kind==='wild'?'🌈 WILD · ':'')+t('קלף מונח בשורה','Card placed in the row'):step.kind==='match'?t('קומבו! +','Combo! +')+step.points:step.kind==='collapse'?t('הקלפים נאספים והשורה נסגרת','Cards collected; the row closes'):step.kind==='shift'?t('⇆ SHIFT · הקלף השמאלי עובר לימין','⇆ SHIFT · leftmost card moves right'):t('משלימים את השורה','Refilling the row');if(step.kind==='collapse')awards[event.player]+=step.points;render();const after=[...document.querySelectorAll('[data-online-card]')],reduced=(document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches);
let mapping=before.map((_,i)=>i);if(step.kind==='swap'){const p=event.swapPos;[mapping[p],mapping[p+1]]=[mapping[p+1],mapping[p]]}else if(step.kind==='placed')mapping.splice(event.pos,0,-1);else if(step.kind==='collapse')mapping=mapping.filter(i=>!previous.removed.includes(i));else if(step.kind==='shift'){mapping.splice(step.shiftIndex,1);if(step.rotate)mapping.push(mapping.shift())}
const animations=[];if(!reduced)after.forEach((el,i)=>{const from=before[mapping[i]]?.rect,to=el.getBoundingClientRect();if(from)animations.push(el.animate([{transform:`translate(${from.left-to.left}px,${from.top-to.top}px)`},{transform:'translate(0,0)'}],{duration:300,easing:'ease-out'}).finished.catch(()=>{}));else animations.push(el.animate([{opacity:0,transform:'translateY(-28px) rotate(-5deg)'},{opacity:1,transform:'none'}],{duration:300}).finished.catch(()=>{}))});await Promise.all(animations);await pause(reduced?30:step.kind==='match'?650:250)}
async function accept(data){latest=data;if(animating)return;if(room&&data.revision===room.revision)return;const events=room?data.events.filter(e=>e.id>seen):[];room=data;reset();error='';if(!events.length){seen=data.events.at(-1)?.id||0;return render()}animating=true;const serial=epoch;awards=data.members.map(m=>m.points);events.forEach(e=>awards[e.player]-=e.score);try{for(const event of events){if(epoch!==serial)break;animationActor=event.player;frame={kind:'before',board:event.before};render();let prev=frame;for(const step of [...event.steps,{kind:'refill',board:event.after}]){await visualStep(step,prev,event,serial);prev=step}seen=event.id}}finally{if(epoch===serial){frame=null;awards=null;animating=false;render();if(latest.revision>room.revision)await accept(latest)}}}
async function refresh(){if(!roomId||busy||animating)return;try{const data=await api('/'+roomId);error='';if(!room){room=data;seen=data.events.at(-1)?.id||0;invite=saved.id===roomId?saved.invite||'':'';joinToken='';history.replaceState(null,'',location.pathname+'#room='+roomId);render()}else await accept(data);error=''}catch(e){error=joinToken&&e.code==='not_member'?'':message(e);render()}}
window.SparkOnline={mount(nextLang){lang=nextLang;render();if(roomId&&!room)refresh();clearInterval(timer);timer=setInterval(()=>{if(root()&&!document.hidden)refresh()},2000)}};
window.addEventListener('online',()=>{if(root())refresh()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&root())refresh()});
if(params.has('room'))document.querySelector('[data-screen="friends"]')?.click();
})();
